class Solution {
public:
    bool backspaceCompare(string s, string t) {
        int i = (int)s.size() - 1, j = (int)t.size() - 1;
        int skip_s = 0, skip_t = 0;
        while (i >= 0 || j >= 0) {
            while (i >= 0) {
                if (s[i] == '#') { skip_s++; i--; }
                else if (skip_s > 0) { skip_s--; i--; }
                else break;
            }
            while (j >= 0) {
                if (t[j] == '#') { skip_t++; j--; }
                else if (skip_t > 0) { skip_t--; j--; }
                else break;
            }
            char c_s = i >= 0 ? s[i] : '\0';
            char c_t = j >= 0 ? t[j] : '\0';
            if (c_s != c_t) return false;
            i--; j--;
        }
        return true;
    }
};

class Solution {
    public boolean backspaceCompare(String s, String t) {
        int i = s.length() - 1, j = t.length() - 1;
        int skipS = 0, skipT = 0;
        while (i >= 0 || j >= 0) {
            while (i >= 0) {
                if (s.charAt(i) == '#') { skipS++; i--; }
                else if (skipS > 0) { skipS--; i--; }
                else break;
            }
            while (j >= 0) {
                if (t.charAt(j) == '#') { skipT++; j--; }
                else if (skipT > 0) { skipT--; j--; }
                else break;
            }
            char cs = i >= 0 ? s.charAt(i) : '\0';
            char ct = j >= 0 ? t.charAt(j) : '\0';
            if (cs != ct) return false;
            i--; j--;
        }
        return true;
    }
}

var backspaceCompare = function(s, t) {
    let i = s.length - 1;
    let j = t.length - 1;
    let skipS = 0;
    let skipT = 0;
    while (i >= 0 || j >= 0) {
        while (i >= 0) {
            if (s[i] === '#') { skipS++; i--; }
            else if (skipS > 0) { skipS--; i--; }
            else break;
        }
        while (j >= 0) {
            if (t[j] === '#') { skipT++; j--; }
            else if (skipT > 0) { skipT--; j--; }
            else break;
        }
        const cs = i >= 0 ? s[i] : '';
        const ct = j >= 0 ? t[j] : '';
        if (cs !== ct) return false;
        i--; j--;
    }
